-- DYNAMIC SPECIFICATIONS SEED
-- Applies Category Templates and generates realistic product specs for all existing seeded products.

DO $$
DECLARE
  product_record RECORD;
  spec_json JSONB;
BEGIN

  -- 1. Update Categories with SpecificationTemplates
  UPDATE Categories SET SpecificationTemplate = '{"General":["In The Box","Model Name","Function Type","Energy Rating","Washing Capacity","Color","Water Consumption"],"Wash Modes":["Quick Wash"],"Convenience":["Child Lock"],"Power & Dimensions":["Power Consumption","Weight","Depth","Height","Width"],"Warranty & Mfg Info":["Warranty Summary","Country of Origin","Manufactured by","Imported by","Packed by"]}'::jsonb WHERE Id = 1;
  UPDATE Categories SET SpecificationTemplate = '{"General":["In The Box","Type","Defrosting Type","Compressor Type","Capacity","Doors","Star Rating","Toughened Glass"],"Performance":["Convertible"],"Compartment Features":["Shelves","Interior Light","Drawers"],"Warranty & Mfg Info":["Warranty Summary","Country of Origin","Manufactured by","Imported by","Packed by"]}'::jsonb WHERE Id = 2;
  UPDATE Categories SET SpecificationTemplate = '{"General":["Model Name","Color","Display Size","Screen Type","Resolution","Smart TV","HDMI Ports","Wi-Fi","Launch Year"],"Video":["Refresh Rate"],"Smart TV Features":["Processor","Apps","OS","Bluetooth"],"Connectivity":["HDMI","USB"],"Audio":["Speaker Type","Sound Technology","Output RMS"],"Power":["Consumption","Requirement"],"Remote & Dimensions":["Remote Control","Weight","Depth","Height","Width"],"Warranty & Mfg Info":["Warranty Summary","Country of Origin","Manufactured by","Imported by","Packed by"]}'::jsonb WHERE Id = 3;
  UPDATE Categories SET SpecificationTemplate = '{"General":["In The Box","Type","Capacity in Tons","Star Rating","Cooling Capacity","Dehumidification","Remote Control"],"Performance":["Sensors"],"Warranty & Mfg Info":["Warranty Summary","Country of Origin","Manufactured by","Imported by","Packed by"]}'::jsonb WHERE Id = 4;
  UPDATE Categories SET SpecificationTemplate = '{"Features":["Product ID"],"Warranty & Mfg Info":["Country of Origin","Manufactured by","Imported by","Packed by"]}'::jsonb WHERE Id = 5;
  UPDATE Categories SET SpecificationTemplate = '{"General":["Model Name","Color","Water Resistant","Headphone Type","Inline Remote","Connectivity","Sales Package","Compatible Devices","Design"],"Product Details":["Sweat Proof","Deep Bass"],"Warranty & Mfg Info":["Warranty Summary","Country of Origin","Manufactured by","Imported by","Packed by"]}'::jsonb WHERE Id = 6;
